package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StrBuilder.contains(char ch)
 */
public class StrBuilder_contains_TriageGen0Test {

    @Test
    public void testContains_EmptyBuilder_ReturnsFalse() {
        StrBuilder sb = new StrBuilder();
        assertFalse("Should return false when builder is empty", sb.contains('a'));
    }

    @Test
    public void testContains_CharExists_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("hello");
        assertTrue("Should return true when character is present", sb.contains('e'));
        assertTrue("Should return true when character is at the start", sb.contains('h'));
        assertTrue("Should return true when character is at the end", sb.contains('o'));
    }

    @Test
    public void testContains_CharDoesNotExist_ReturnsFalse() {
        StrBuilder sb = new StrBuilder("abc");
        assertFalse("Should return false when character is not present", sb.contains('z'));
    }

    @Test
    public void testContains_SingleCharacterMatch_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("a");
        assertTrue("Should return true for single character match", sb.contains('a'));
    }

    @Test
    public void testContains_SpecialCharacters_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("!@# ");
        assertTrue("Should handle special characters", sb.contains('!'));
        assertTrue("Should handle spaces", sb.contains(' '));
    }

    @Test
    public void testContains_CaseSensitivity_ReturnsCorrectResult() {
        StrBuilder sb = new StrBuilder("A");
        assertTrue("Should find uppercase", sb.contains('A'));
        assertFalse("Should not find lowercase if only uppercase exists", sb.contains('a'));
    }

    @Test
    public void testContains_LargeBuffer_ReturnsTrue() {
        // Testing the loop range and size logic
        StringBuilder largeStr = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            largeStr.append('x');
        }
        largeStr.append('y');
        StrBuilder sb = new StrBuilder(largeStr.toString());

        assertTrue("Should find character in large buffer", sb.contains('y'));
        assertFalse("Should not find character not in large buffer", sb.contains('z'));
    }
}
